import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';

const HISTO_GAP = {
  status: 'asset_required' as const,
  summary:
    'Microscopic feature guides, stain expectations, and diagnostic criteria are implemented; genuine licensed light/EM micrographs are NOT yet bundled locally (link external Histology Guide & UMich virtual slides; never substitute fake micrographs).',
  missingAssets: ['Verified CC-BY / CC0 high-resolution virtual light-microscopy slide micrographs with scale bars'],
};

function makeHistChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  summary: string,
  stainInfo: string,
  diagnosticPair: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'histology',
    chapterCode: `C${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['secondary_premed', 'medical_foundations', 'allied_health', 'graduate_research'],
    curriculumMappings: [
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Years 1–2', unitOrModule: `General & Systemic Histology (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'in_cbse_bio_11_12', gradeOrYear: 'Class XI', unitOrModule: 'Structural Organisation in Animals', status: 'elective' },
      { frameworkId: 'anat_soc_core', gradeOrYear: 'BS / Graduate', unitOrModule: `Microanatomy: ${chapterTitle}`, status: 'recommended' },
    ],
    prerequisites: ['Cell structure & primary organelles (Domain B)', 'H&E basophilia vs eosinophilia principles'],
    learningObjectives: [
      `Identify hallmark cellular layers and diagnostic microscopic features of ${chapterTitle.toLowerCase()}.`,
      `Predict expected staining appearance under ${stainInfo}.`,
      `Relate microscopic tissue architecture directly to physiological function and common histopathological disruptions.`,
    ],
    depthExplanations: {
      secondary_premed: `${summary} Under light microscopy, cells and supporting extracellular fibres organize into recognizable layers tailored to mechanical protection, transport, or secretion.`,
      medical_foundations: `${mechanisms.join(' ')} Expected stain profile: ${stainInfo}. Note: consult verified external virtual microscopy slide boxes while local licensed micrographs remain Asset Required.`,
      allied_health: `Understanding normal ${chapterTitle.toLowerCase()} microanatomy helps correlate biopsy reports, mucosal barrier health, and specimen fixation protocols.`,
      graduate_research: `Quantitative stereology, basement-membrane immunohistochemistry, and polarized extracellular matrix imaging resolve spatial cell-state transitions across ${chapterTitle.toLowerCase()}.`,
    },
    keyConcepts: [
      { term: 'Primary Tissue Hallmarks', definition: summary },
      { term: 'Standard Stain & Magnification', definition: stainInfo },
      { term: 'Diagnostic Correlation', definition: clinical },
    ],
    keyFacts: [
      `Expected histological stain protocol: ${stainInfo}.`,
      'Local H&E micrographs are strictly marked Asset Required; use external Histology Guide / UMich links for real virtual slides.',
    ],
    mechanisms,
    comparisonTable: { columnA: diagnosticPair.colA, columnB: diagnosticPair.colB, rows: diagnosticPair.rows },
    misconceptions: [
      { misconception: 'Diagrammatic colour schematics show true H&E histology appearance.', correction: '2D schematics teach spatial organization only; real virtual microscopy slides (linked externally) must be inspected for nuclear chromatin and matrix texture.' },
      { misconception: 'Fixation preserves tissue instantaneously without shrinkage artefacts.', correction: 'Formalin-fixed paraffin embedding extracts water/lipids, creating characteristic retraction clefts and clearing out unstained adipocytes/glycogen.' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} integrates cell polarity, extracellular support, and vascular/neural interfaces observable under ${stainInfo}. Genuine local slide photos remain honestly flagged as Asset Required.`,
    keyTakeaways: [
      summary,
      `Key preparation/stain: ${stainInfo}.`,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'human_anatomy', relation: 'Gross 3D organs contain the layered microanatomy described here.' },
      { domainId: 'pathology', relation: 'Diagnostic histopathology evaluates cellular atypia and inflammation against this normal baseline.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['microscopy', '2d_diagram', 'structured_text'],
    diagram: {
      id: `diag-c${num}`,
      title: `${chapterTitle} — Microscopic Architectural Layers`,
      kind: 'hierarchy',
      caption: `${summary} (Stain reference: ${stainInfo})`,
      disclaimer: 'Conceptual histological layer map — NOT a real microscope photograph (Asset Required).',
      nodes: [
        { id: 'n1', label: 'Apical / Functional Zone', sublabel: mechanisms[0]?.slice(0, 62) || summary.slice(0, 60), tone: 'teal' },
        { id: 'n2', label: 'Mid / Parenchymal Zone', sublabel: stainInfo, tone: 'blue' },
        { id: 'n3', label: 'Support / Stroma & Vessels', sublabel: 'Basement membrane, collagen & capillaries', tone: 'amber' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Functional specialization' },
        { from: 'n2', to: 'n3', label: 'Metabolic & mechanical support' },
      ],
    },
    assetDisclosure: HISTO_GAP,
    activity: {
      title: `Virtual Slide Identification Walkthrough (${chapterTitle})`,
      kind: 'interpretation',
      prompt: `Open the external Histology Guide or UMich Slide Box link, locate ${chapterTitle}, set 100× then 400× magnification, and list three diagnostic structures using ${stainInfo}.`,
      keyTakeaway: mechanisms[0] ?? summary,
    },
    readingKeys: ['ap_ch4_tissues', 'histology_guide_slidebox', 'umich_histology_hub'],
    shortAnswers: [
      { id: `sa-c${num}-1`, prompt: `List three distinguishing light-microscopic features that confirm ${chapterTitle} at 400× on H&E.`, expectedPoints: mechanisms.slice(0, 2), modelAnswer: mechanisms.join(' '), level: 'medical_foundations' },
      { id: `sa-c${num}-2`, prompt: `Explain why ${stainInfo} is chosen to visualize the key components of ${chapterTitle}.`, expectedPoints: ['Chromophore affinity for basophilic/acidophilic or mucin/elastic structures', 'Contrast against adjacent stroma'], modelAnswer: `${stainInfo} creates differential contrast between nucleic acids, cytoplasmic proteins, and specialized matrix or secretion granules.`, level: 'secondary_premed' },
      { id: `sa-c${num}-3`, prompt: `Connect one structural microanatomical defect in ${chapterTitle} to clinical pathophysiology.`, expectedPoints: [clinical], modelAnswer: clinical, level: 'clinical_applied' },
    ],
    appliedCase: {
      id: `app-c${num}-1`,
      title: `Biopsy & Fixation Correlation: ${chapterTitle}`,
      scenario: `A teaching specimen from ${chapterTitle.toLowerCase()} is evaluated using ${stainInfo} alongside adjacent stromal landmarks.`,
      questions: [`Which cellular or matrix feature confirms tissue origin?`, `How does this structure underlie normal physiology?`],
      workedSolution: `${mechanisms[0]} Clinically, ${clinical}`,
      level: 'medical_foundations',
    },
    selfChecks: mcqs,
  };
}

